package com.storemate.backend.web;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.test.context.bean.override.mockito.MockitoBean;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class SocialLoginWorkflowTest {
 @MockitoBean SocialOAuthGateway gateway;@Autowired SocialLoginController controller;
 @BeforeEach void setup(){when(gateway.configured("google")).thenReturn(true);when(gateway.authorize(eq("google"),anyString())).thenAnswer(a->"https://accounts.google.com/authorize?state="+a.getArgument(1));when(gateway.exchange("google","test-code")).thenReturn(new SocialOAuthGateway.Identity(UUID.randomUUID().toString(),"소셜 사용자"));}
 @Test void loginNeedsProviderCallbackAndPrivatePollingSecret(){var start=controller.start(new SocialLoginController.Start("google","staff"));assertNotEquals(start.state(),start.pollSecret());assertEquals("pending",controller.result(new SocialLoginController.Poll(start.state(),start.pollSecret())).status());assertThrows(ApiException.class,()->controller.result(new SocialLoginController.Poll(start.state(),start.state())));controller.callback("google",start.state(),"test-code",null);var result=controller.result(new SocialLoginController.Poll(start.state(),start.pollSecret()));assertEquals("complete",result.status());assertEquals("staff",result.login().account().role());assertNotNull(result.login().token());assertEquals("expired",controller.result(new SocialLoginController.Poll(start.state(),start.pollSecret())).status());}
 @Test void cancellationAndMissingCredentialsNeverPretendLoginSuccess(){assertThrows(ApiException.class,()->controller.start(new SocialLoginController.Start("kakao","staff")));var start=controller.start(new SocialLoginController.Start("google","owner"));controller.callback("google",start.state(),null,"access_denied");assertEquals("error",controller.result(new SocialLoginController.Poll(start.state(),start.pollSecret())).status());verify(gateway,never()).exchange(anyString(),anyString());}
 @Test void callbackCannotBeReusedOrSwitchedToAnotherProvider(){var start=controller.start(new SocialLoginController.Start("google","owner"));assertThrows(ApiException.class,()->controller.callback("kakao",start.state(),"test-code",null));controller.callback("google",start.state(),"test-code",null);assertThrows(ApiException.class,()->controller.callback("google",start.state(),"test-code",null));}
}
